import{U as e,W as t,nt as n,t as r}from"./chunks/framework.DRwsyrlO.js";import"./chunks/assets.DbQFHwAY.js";var i=JSON.parse(`{"title":"固定空间站核心：空气、温度、重力与地图","description":"了解固定空间站核心 2.0 的环境设置、三种重力模式、白色球罩和 M 星图可见性的实际含义。","frontmatter":{"title":"固定空间站核心：空气、温度、重力与地图","description":"了解固定空间站核心 2.0 的环境设置、三种重力模式、白色球罩和 M 星图可见性的实际含义。"},"headers":[],"relativePath":"skyblock/stations.md","filePath":"skyblock/stations.md"}`),a={name:`skyblock/stations.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="固定空间站核心-让太空建筑适合生活" tabindex="-1">固定空间站核心：让太空建筑适合生活 <a class="header-anchor" href="#固定空间站核心-让太空建筑适合生活" aria-label="Permalink to “固定空间站核心：让太空建筑适合生活”">​</a></h1><p>空间站不只需要一个外壳。固定空间站核心可以为建筑设置空气、温度和重力区域，让太空中的房间具备对应的生活环境。</p><p>本页说明当前部署的 <strong>2.0.0</strong> 功能。具体合成、界面入口和参数范围以匹配客户端与服内说明为准，操作截图待补充。</p><figure class="campaign-photo space-photo"><img src="/images/skyblock/station-dock.png" alt="地火一号公共空间站与建筑外的飞船" width="1600" height="900" loading="lazy"><figcaption>「地火一号」公共空间站与停靠的飞船</figcaption></figure><h2 id="先分清固定站与飞船" tabindex="-1">先分清固定站与飞船 <a class="header-anchor" href="#先分清固定站与飞船" aria-label="Permalink to “先分清固定站与飞船”">​</a></h2><p>这里介绍的是<strong>固定建筑的空间站核心</strong>，不是把整座空间站自动变成可驾驶飞船。造船与航行请看 <a href="./spaceflight.html#ship">飞船准备</a>。</p><p>设置需要满足核心、站主权限及区域不重叠等条件。正式客户端应匹配当前空间站组件，旧版组件不能视为协议通用。</p><h2 id="空气和温度-要一起规划" tabindex="-1">空气和温度，要一起规划 <a class="header-anchor" href="#空气和温度-要一起规划" aria-label="Permalink to “空气和温度，要一起规划”">​</a></h2><p>核心可设置空气／温度区域半径及相应环境参数。规划住处或车间时，应确认活动位置处于合适的区域里。</p><p><strong>有空气不等于所有环境都安全。</strong> 温度不合适仍可能造成危害，进出区域时也要准备对应装备。</p><p>白色半透明球罩用于显示空气／温度场范围，是视觉标识，<strong>不是实体墙、防爆罩或领地保护</strong>。</p><figure class="campaign-photo space-photo"><img src="/images/skyblock/station-habitat.png" alt="空间站建筑外围可见白色半透明球罩" width="1600" height="900" loading="lazy"><figcaption>空间站上方的环境范围球罩</figcaption></figure><h2 id="重力有三种模式" tabindex="-1">重力有三种模式 <a class="header-anchor" href="#重力有三种模式" aria-label="Permalink to “重力有三种模式”">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>玩家体验</th></tr></thead><tbody><tr><td>自由漂浮</td><td>适合按无重力方式活动的区域</td></tr><tr><td>完全重力</td><td>在区域中使用对应的完整重力体验</td></tr><tr><td>脚下地板吸附</td><td>按脚下地板组织站内行走体验</td></tr></tbody></table><p>重力的范围、模式与强度由站点设置决定，不等于整个维度的重力都被统一改变。先确认当前参数，再调整建筑布局。</p><h2 id="m-星图的公共与私人站点" tabindex="-1">M 星图的公共与私人站点 <a class="header-anchor" href="#m-星图的公共与私人站点" aria-label="Permalink to “M 星图的公共与私人站点”">​</a></h2><p>当前可在 <strong>M 星图</strong>中查看对应维度的公共站点或自己的私人站点，并管理站点的地图可见性。</p><p>“私人”控制的是<strong>地图显示</strong>，不代表禁止其他玩家进入，不是访问白名单或防熊保障。敏感位置与物资仍需按实际保护规则安排。</p><h2 id="当前没有空间站-n-键自动导航" tabindex="-1">当前没有空间站 N 键自动导航 <a class="header-anchor" href="#当前没有空间站-n-键自动导航" aria-label="Permalink to “当前没有空间站 N 键自动导航”">​</a></h2><p>空间站扩展的 N 目的地、首次到访解锁等属于候选版本内容，<strong>当前生产 2.0.0 尚未开放</strong>。不能把原生星体导航与空间站自动导航混为一谈。</p><h2 id="开始建站前" tabindex="-1">开始建站前 <a class="header-anchor" href="#开始建站前" aria-label="Permalink to “开始建站前”">​</a></h2><ul><li>按当前服内配方制作核心，确认所在区域与放置权限。</li><li>规划空气、温度与重力的覆盖范围，避免与其他区域冲突。</li><li>设置适合当前活动与装备的环境，别只看球罩就判定安全。</li><li>确认公共／私人地图显示是否符合自己的意愿。</li><li>核工业仍需考虑熔毁与辐射，岛屿防爆或站内空气不能豁免核风险。</li></ul><p><a href="./spaceflight.html">航天发展</a> · <a href="./graduation.html">离岛毕业规则</a> · <a href="./../guides/">返回知识库</a></p><p>资料依据：2026-11-20 内容交接，空间站扩展 2.0.0。</p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};